GATES=('causal_preentry_availability','identifiable_incremental_claim','no_response_leakage','no_selection_parameter_search','no_symbol_context_mining','support_measurable','dependence_calibratable','execution_friction_path','eur200_structural_possible','disjoint_confirmation_path','finite_compute','unknown_cost_not_zero')
DIMENSIONS=('CAUSAL_IDENTIFIABILITY','INCREMENTAL_INFORMATION_DISTINCTNESS','PREENTRY_OBSERVABILITY','REQUIRED_MODALITY_ALREADY_AVAILABLE','SYNCHRONIZATION_FEASIBILITY','SUPPORT_MEASURABILITY','DEPENDENCE_GEOMETRY_IDENTIFIABILITY','COMPUTE_FEASIBILITY','ADDITIONAL_DATA_BURDEN','EXECUTION_AND_FRICTION_OBSERVABILITY_PATH','TIME_TO_GENUINE_ECONOMIC_TEST','BREADTH_AND_GENERALIZATION_PATH','DISJOINT_CONFIRMATION_PATH')
BINDINGS={INPUT:'fa01029ed0ac8bee799594a4d08cc053ce55aaedce3b3c2a4375435a3048234b',PROPOSALS:'e1ab6c79c555b84e1edf0141c50f95c086c4c74b7e0188497cddf065f49d8396'}
def sha(data):return hashlib.sha256(data).hexdigest()
def functional():
    return {'schema':'mxm.v4.strict-preoutcome-v2.prospective-selection-functional.v1','status':'FROZEN_PROSPECTIVE_BEFORE_APPLICATION','objective':'Maximize rate of genuine decision-relevant economic information per time and resource, constrained by causal identification, valid inference, execution realism and capital survival; no historical edge prior.','hard_gates':list(GATES),'mandatory_dimensions':list(DIMENSIONS),'admissibility_law':'Every hard gate must be PASS. UNKNOWN blocks current selection without asserting scientific null; FAIL blocks this exact proposal only. Calibration possibility is required, not completed power or error-control trials.','partial_order':{'dimensions':list(DIMENSIONS),'certification_order':['CERTIFIED_WORSE','CERTIFIED_EQUAL','CERTIFIED_BETTER'],'unknown':'INCOMPARABLE_NOT_EQUAL_NOT_ZERO','objective_burden_law':'Compare data, compute and time burdens only with auditable bounds. Qualitative availability is not a bound on economic information rate. No weighted score, numeric VOI, outcome prior, candidate ID or random tiebreak.','dominance':'A dominates B only if all 13 pairwise comparisons are certified nonworse and at least one scientifically relevant information/identification/inference/execution/generalization dimension is strictly better. Convenience-only improvements cannot establish information preference.','unique_choice':'Require exactly one currently admissible candidate to robustly dominate every other not-failed candidate. Unresolved candidates remain possible competitors; they cannot be discarded merely because certification is missing.','tie':'Multiple nondominated or incomparable possibilities means unresolved.'},'minimal_discriminator_law':'Address the first unsatisfied necessary scientific gate before acquiring more price history. A semantic identification certificate can resolve deterministic redundancy without market outcomes. It may reduce contenders; it cannot guarantee a unique winner or replace later path and burden evidence.','power_duration_downstream':True,'power_lower95_bound_preserved':0.80,'preserved_plan':'BREADTH_FIRST_THEN_DEPTH_SECOND','project_adaptivity':'Prior research and adaptive selection history are not erased. Future development survivors require selection payment and genuinely disjoint confirmation.','selection_read_allowlist':sorted(ALLOWLIST),'source_bindings':BINDINGS}
SCIENCE={'CAUSAL_IDENTIFIABILITY','INCREMENTAL_INFORMATION_DISTINCTNESS','PREENTRY_OBSERVABILITY','DEPENDENCE_GEOMETRY_IDENTIFIABILITY','EXECUTION_AND_FRICTION_OBSERVABILITY_PATH','BREADTH_AND_GENERALIZATION_PATH','DISJOINT_CONFIRMATION_PATH'}
def admissibility(gates):
    require(set(gates)==set(GATES),'HARD_GATE_SCHEMA')
    require(all(v in {'PASS','FAIL','UNKNOWN'} for v in gates.values()),'HARD_GATE_VALUE')
    return 'FAIL' if 'FAIL' in gates.values() else ('UNKNOWN' if 'UNKNOWN' in gates.values() else 'PASS')
def dominates(comparison):
    require(set(comparison)==set(DIMENSIONS),'PAIRWISE_SCHEMA')
    require(all(v in {'CERTIFIED_WORSE','CERTIFIED_EQUAL','CERTIFIED_BETTER','UNKNOWN'} for v in comparison.values()),'PAIRWISE_VALUE')
    return all(v in {'CERTIFIED_EQUAL','CERTIFIED_BETTER'} for v in comparison.values()) and any(comparison[k]=='CERTIFIED_BETTER' for k in SCIENCE)
def select(rows,pairwise):
    require(len({r['information_source'] for r in rows})==len(rows),'DUPLICATE_SOURCE')
    for r in rows:admissibility(r['hard_gates'])
    possible=[r for r in rows if admissibility(r['hard_gates'])!='FAIL']
    winners=[]
    for r in possible:
        if admissibility(r['hard_gates'])!='PASS':continue
        others=[q for q in possible if q['information_source']!=r['information_source']]
        if all(dominates(pairwise.get((r['information_source'],q['information_source']),{k:'UNKNOWN' for k in DIMENSIONS})) for q in others):winners.append(r['information_source'])
    require(len(winners)<=1,'INCONSISTENT_DOMINANCE_CERTIFICATES')
    return winners[0] if winners else None

def assess(d,proposals,f):
    require(f==functional(),'FUNCTIONAL_DRIFT')
    require(d['current_structural_execution']['account_equity_eur']==200 and d['current_structural_execution']['identity_count_with_accepted_current_structural_gates']==1575,'CURRENT_STRUCTURAL_METADATA_DRIFT')
    require(len(d['identities'])==1575 and len(d['context_geometry'])==29,'STRUCTURAL_UNIVERSE_DRIFT')
    candidates=proposals['candidates'];require(len(candidates)==12,'CANDIDATE_COUNT')
    require(proposals['selection']['selected_source'] is None and proposals['selection']['selected_mechanism'] is None,'PREEXISTING_SELECTION')
    rows=[]
    for i,c in enumerate(candidates):
        extra=i in (4,5,6,7,8,9,10)
        gates={k:'UNKNOWN' for k in GATES}
        for k in ['no_response_leakage','no_selection_parameter_search','no_symbol_context_mining','eur200_structural_possible','finite_compute','unknown_cost_not_zero']:gates[k]='PASS'
        if not extra:gates['causal_preentry_availability']='PASS'
        # Exact semantic inference only: the first feature is explicitly already in its own baseline.
        if i==0:gates['identifiable_incremental_claim']='FAIL'
        missing=['Exact Phi_i and own baseline B_t maps, domains, units and causal available information sigma-algebras','Proof or counterexample for Phi_i measurable with respect to B_t; causal innovation witness for genuinely additional information','Exact authentic support mask for the feature/response schedule, without response values','Dependence unit, overlap graph and estimand aggregation law enabling later calibration','Point-in-time authentic execution/friction route and capital-survival constraints; costs remain unknown','Auditable bounds on time and resource burden to a genuine information test','Disjoint confirmation boundary and provenance plan']
        if extra:missing.append('Authoritative effective timestamps and cohort/linkage or additional-modality schema contract')
        if i==0:missing=['No structural acquisition can make the exact hourly-location feature incremental beyond the baseline that already includes it; a mechanism change is not authorized by this comparison.']
        dimensions={k:'UNRESOLVED' for k in DIMENSIONS}
        dimensions['REQUIRED_MODALITY_ALREADY_AVAILABLE']='M5_SCHEMA_AVAILABLE_ADDITIONAL_CONTRACT_UNCERTIFIED' if extra else 'ACCEPTED_M5_MODALITY_AVAILABLE'
        dimensions['COMPUTE_FEASIBILITY']='FINITE_STREAMING_ARCHITECTURE_OPERATION_COUNT_UNRESOLVED'
        dimensions['PREENTRY_OBSERVABILITY']='ADDITIONAL_POINT_IN_TIME_CONTRACT_UNRESOLVED' if extra else 'COMPLETED_M5_BARS_PREENTRY'
        dimensions['INCREMENTAL_INFORMATION_DISTINCTNESS']='DETERMINISTIC_BASELINE_REDUNDANCY' if i==0 else 'CAUSAL_NONREDUNDANCY_CERTIFICATE_MISSING'
        rows.append({'information_source':c['information_source'],'frozen_mechanism_sha256':sha(canonical(c)),'hard_gates':gates,'HARD_ADMISSIBILITY_STATUS':admissibility(gates),'CAUSAL_IDENTIFIABILITY_STATUS':'EXACT_BASELINE_REDUNDANT' if i==0 else 'UNKNOWN_FORMAL_MAPS_NOT_FIXED','EXISTING_MODALITY_SUFFICIENCY':'M5_FIELDS_AVAILABLE_NOT_A_COMPLETE_IDENTIFIABLE_DESIGN' if not extra else 'ADDITIONAL_AUTHENTIC_CONTRACT_UNCERTIFIED','ADDITIONAL_AUTHENTIC_MODALITY_REQUIRED':extra,'EXACT_SUPPORT_MEASURABILITY_STATUS':'SUMMARY_ONLY_EXACT_MASK_UNCERTIFIED','EXACT_SYNCHRONIZATION_STATUS':'EXACT_CAUSAL_READSET_AND_MASK_UNCERTIFIED','DEPENDENCE_IDENTIFIABILITY_STATUS':'SHARED_CALENDAR_CONTEXT_DEPENDENCE_UNIT_NOT_EXACTLY_SPECIFIED','COMPUTE_STATUS':'FINITE_PASS_POSSIBLE_EXACT_OPERATION_BOUND_UNKNOWN','EXECUTION_INFORMATION_PATH_STATUS':'CURRENT_EUR200_STRUCTURALLY_POSSIBLE_HISTORICAL_FRICTION_ROUTE_NOT_CERTIFIED_UNKNOWN_NEVER_ZERO','GENERALIZATION_PATH_STATUS':'ALL1575_PRESERVED_CONTEXT_STRUCTURAL_COHORT_LAW_UNCERTIFIED','CONFIRMATION_PATH_STATUS':'GENUINELY_DISJOINT_REQUIRED_EXACT_PROVENANCE_BOUNDARY_UNCERTIFIED','SELECTION_FUNCTIONAL_POSITION':'EXACT_PROPOSAL_INADMISSIBLE_NOT_GLOBAL_NULL' if i==0 else 'POSSIBLE_BUT_NOT_ADMISSIBLE_INCOMPARABLE','dimensions':dimensions,'EXACT_UNRESOLVED_STRUCTURAL_QUANTITIES':missing})
    selected=select(rows,{})
    require(selected is None,'UNEXPECTED_SELECTION')
    return {'schema':'mxm.v4.strict-preoutcome-v2.functional-assessment.v1','status':'SELECTION_UNRESOLVED_MINIMUM_STRUCTURAL_DISCRIMINATOR_REQUIRED','functional_sha256':sha(canonical(f)),'input_bindings':BINDINGS,'candidate_definitions_sha256':sha(canonical(candidates)),'candidate_count':12,'assessments':rows,'selected_source':selected,'selected_mechanism':None,'complete_information_design':False,'currently_admissible_count':0,'exact_semantic_fail_count':1,'unknown_admissibility_count':11,'possible_contender_sources':[x['information_source'] for x in rows[1:]],'pairwise_position':'No certified robust pairwise dominance; all eleven possible contenders remain incomparable, not equally valuable.','selection_rate_numeric_estimate':None,'unknown_cost_is_zero':False,'new_outcomes_used':False,'next_action':NEXT}

def gap(a):
    return {'schema':'mxm.v4.strict-preoutcome-v2.selection-identifiability-gap.v1','status':'FROZEN_FIRST_NECESSARY_STRUCTURAL_GATE_IDENTIFIED','assessment_sha256':sha(canonical(a)),'first_shared_blocker':'The mapping from each proposed extra-information feature Phi_i to its own-information baseline B_t is not formally specified. Incremental information cannot be identified until deterministic baseline redundancy is excluded.','exact_quantity':'For each of the eleven possible contenders: is sigma(Phi_i) contained in sigma(B_t) on the causally available structural domain? If not, identify a legal nonredundancy witness and the additional observable read set. This is structural measurability, not empirical conditional dependence or predictive strength.','known_exact_redundancy':{'source':a['assessments'][0]['information_source'],'proof':'The first proposal uses completed hourly high-low price location, and its frozen own-information baseline explicitly contains hourly price location. Hence Phi is already B-measurable. This blocks only the exact proposal, not the source family.','history_used':False},'why_first':'Every surviving candidate lacks an exact incremental identification certificate; more bars cannot specify a missing estimand or baseline. Addressing this necessary gate precedes support sampling or price history.','unresolved_after_discriminator':['Exact support/synchronization and dependence contracts','Execution/friction and survival path','Auditable time/resource bounds','Generalization and disjoint-confirmation contract'],'minimum_claim_scope':'Smallest first-stage logical discriminator, not a proven globally minimal guaranteed winner-producing dataset. Multiple contenders can remain; no promised unique winner.','no_power_as_mechanism_selection':True,'no_duration_as_mechanism_selection':True}

def discriminator(a,g):
    fields=['candidate_definition_sha256','exact_baseline_map_B_t','exact_feature_map_Phi_i','input_domain_units','preentry_information_readset','availability_timestamp_map','sigma_containment_verdict','constructive_nonredundancy_witness_or_redundancy_proof','cohort_or_linkage_domain','semantic_equivalence_to_frozen_proposal_proof']
    return {'schema':'mxm.v4.strict-preoutcome-v2.minimum-structural-discriminator-plan.v1','status':'FROZEN_NOT_EXECUTED_PENDING_INDEPENDENT_AUDIT','identifiability_gap_sha256':sha(canonical(g)),'EXACT_MISSING_STRUCTURAL_QUANTITY':g['exact_quantity'],'WHICH_CURRENT_CANDIDATES_IT_CAN_DISTINGUISH':a['possible_contender_sources'],'excluded_from_requested_packet':{'UNIVARIATE_PRICE_STATE':'Known exact baseline redundancy; no more market support resolves it.'},'WHY_IT_IS_OUTCOME_BLIND':'Compare mathematical information maps and authentic availability semantics only. Use synthetic domain witnesses, never observed return, price response, PNL, historical classifications or successful identities. A witness proves possible nonredundancy, not profitability.','EXACT_DATA_MODALITY_REQUIRED':'Prospective design-semantic certificate packet: one shared explicit own-information baseline and at most eleven candidate-specific certificates. This is not a market-data capture.','certificate_fields':fields,'WHETHER_EXISTING_ACCEPTED_DATA_CAN_ANSWER_IT':'Existing frozen proposals and schema can anchor a design-semantics audit. Accepted market rows are neither needed nor sufficient to define missing exact maps. Metadata-only linkage/availability evidence may be required for relational, session, quote, term and financing candidates; if absent, stop that certificate unresolved without broker or raw data.','WHETHER_RAW_MARKET_RESPONSE_IS_REQUIRED':False,'WHETHER_BROKER_CONTACT_WOULD_BE_REQUIRED':False,'WHETHER_REDECRYPTION_WOULD_BE_REQUIRED':False,'MINIMUM_DATA_VOLUME_OR_TIME_WINDOW_IF_STRUCTURALLY_DERIVABLE':{'authentic_market_rows':0,'historical_time_window':None,'price_history_required':False,'shared_baseline_records':1,'candidate_certificate_records_maximum':11,'reason':'One certificate per independently distinct contender is necessary in the worst case to avoid silently discarding a competitor. Stop early if a subsequent audited functional has robust dominance; do not assume all eleven must require new data.'},'COMPUTE_BURDEN':'Finite algebraic measurability and read-set audit; synthetic constructive witnesses only where exact maps permit them. No Monte Carlo, empirical response, power trial or bar-duration search. Exact operation bound depends on formulas and is not guessed.','CAUSAL_TIMESTAMP_REQUIREMENT':'Each read must have authentic effective and availability timestamp <= proposed entry; completed bars use close timestamps; revisions cannot be backdated. Missing proof yields UNKNOWN.','SYNCHRONIZATION_REQUIREMENT':'State a required identity-time readset from the exact feature map; prove availability from schemas or accepted metadata. Do not compute real masks in this plan stage.','STOP_RULE':['Do not execute this plan in the current task.','In a separately authorized semantic audit, stop a candidate as UNKNOWN if no exact formula faithful to the frozen prose or authoritative availability proof can be given. No mechanism edits to improve comparative position.','Certificate showing deterministic redundancy blocks only that exact proposal. Certificate showing nonredundancy does not certify predictive or economic information.','Reapply the frozen functional only with independently audited structural certificates. If no robust unique admissible choice exists, stop unresolved and identify the next necessary structural cut; do not acquire deeper history.'],'WHY_ANY_LARGER_ACQUISITION_WOULD_BE_PREMATURE':'More observed bars cannot resolve an unspecified baseline/estimand. Time/resource efficiency, execution realism and valid inference cannot be inferred from row counts alone. Deep duration remains downstream of one frozen complete information design.','execution_in_this_task':False,'new_structural_information_acquired':False,'new_market_data_acquired':False,'power_trials':0,'duration_selected':False,'required_stop':NEXT}

def build_root(root,reads=None):
    reads=[] if reads is None else reads
    with io_firewall(root,ALLOWLIST,reads):
        data={p:(Path(root)/p).read_bytes() for p in sorted(ALLOWLIST)}
    for p,h in BINDINGS.items():require(sha(data[p])==h,'INPUT_HASH_DRIFT:'+p)
    f=json.loads(data[FUNCTIONAL]);require(canonical(f)==data[FUNCTIONAL],'FUNCTIONAL_CANONICAL_BYTES')
    with io_firewall(root,set(),reads):
        a=assess(json.loads(data[INPUT]),json.loads(data[PROPOSALS]),f);g=gap(a);p=discriminator(a,g)
    return {ASSESSMENT:a,GAP:g,PLAN:p}
